long long int min_num, min_den;
long long int best_a, best_b;
long long int gcdLL(long long int a, long long int b)
{
    while (b != 0) {
        long long int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
// Function to evaluate and update minimum ratio
void check_ratio(long long int x, long long int y, long long int b, long long int a)
{
    if (a < 0) return;
    long long int divisor = gcdLL(a, b);
    a /= divisor;
    b /= divisor;
    long long int numerator = abs(b * x - a * y);
    long long int denominator = b * y;
    long long int g = gcdLL(numerator, denominator);
    numerator /= g;
    denominator /= g;
    if (numerator * min_den < min_num * denominator) {
        min_num = numerator;
        min_den = denominator;
        best_a = a;
        best_b = b;
        return;
    }
    if (numerator * min_den == denominator * min_num) {
        if (b < best_b) {
            best_a = a;
            best_b = b;
            return;
        }
        if (b > best_b) {
            return;
        }
        if (a < best_a) {
            best_a = a;
            best_b = b;
            return;
        }
    }
}
